def find_primes_dividing_an(limit):
    primes_dividing_an = []
    for p in range(2, limit):
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
        if not is_prime:
            continue

        # Check if p divides a_n = 6^n + 2^n + 3^n - 1 for some n
        # The sequence is periodic with period p-1 for p > 3
        # For p=2, a_n = 6^n + 2^n + 3^n - 1 = 0 + 0 + 1 - 1 = 0 (for n >= 1)
        # For p=3, a_n = 0 + 2^n + 0 - 1 = 2^n - 1 (for n >= 1)

        found = False
        if p == 2:
            found = True
        elif p == 3:
            # a_n = 2^n - 1 (mod 3). For n=2, 2^2-1 = 3 = 0 (mod 3)
            found = True
        else:
            # For p > 3, check n = 1, 2, ..., p-1
            for n in range(1, p):
                an = (pow(6, n, p) + pow(2, n, p) + pow(3, n, p) - 1) % p
                if an == 0:
                    found = True
                    break

        if found:
            primes_dividing_an.append(p)
    return primes_dividing_an

