def find_primes_dividing_an_large(limit):
    primes_dividing_an = []
    for p in range(2, limit):
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
        if not is_prime:
            continue

        found = False
        if p == 2:
            found = True
        elif p == 3:
            found = True
        else:
            # Check n up to p-1. For p > 3, the period of 6^n, 2^n, 3^n divides p-1.
            # Wait, the period actually divides lcm(ord_p(6), ord_p(2), ord_p(3)).
            # Since ord_p(x) | p-1, the period divides p-1.
            # But what if p divides 6, 2, or 3?
            # If p=2, 6^n+2^n+3^n-1 = 0+0+1-1 = 0 (for n >= 1)
            # If p=3, 6^n+2^n+3^n-1 = 0+2^n+0-1 = 2^n-1 (for n >= 1)
            # So for p=2, 3, we've already handled it.
            for n in range(1, p):
                an = (pow(6, n, p) + pow(2, n, p) + pow(3, n, p) - 1) % p
                if an == 0:
                    found = True
                    break

        if found:
            primes_dividing_an.append(p)
    return primes_dividing_an

