def check_all_primes(limit):
    primes = []
    for p in range(2, limit):
        is_prime = True
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(p)

    no_solution_primes = []
    for p in primes:
        found = False
        if p == 2:
            found = True
        elif p == 3:
            found = True
        else:
            for n in range(1, p):
                if (pow(2, n, p) + 1) * (pow(3, n, p) + 1) % p == 2 % p:
                    found = True
                    break
        if not found:
            no_solution_primes.append(p)
    return no_solution_primes

